 new[sid]={'name':a['common_names'].split(' | ')[0],'latin':n,'rare':'Muy rara'if a['source_rarity']=='Muy raro'else a['source_rarity'],'kind':fkind.get(f,kind[cl]),'color':family_color.get(f,colors[cl]),'habitats':h,'times':hours,'seasons':['primavera','verano','otono','invierno'],'special':(['Albino']if source in albino else[])+(['Melánico']if source in melanic else[])+['Notable'],'dimorphism':source in sex,'family':f,'taxonomy':{'className':cl,'subClass':a['source_subgroup']},'origin':'sa3230','sourceScientific':source,'sourceSpeciesIds':a['source_species_ids'].split(' | '),'taxonomicStatus':status,'taxonomyNotes':notes,'artProfile':slug(n).replace('_','-')}
 if source in sex:dim[sid]={'type':'sa3230','description':sex[source]}
