source=[]
for p in pres:
 row=int(p['source_row']);n=p['Nombre científico'];source.append({'sheet':p['source_sheet'],'row':row,'sourceHexId':p['ID hex'],'sourceSpeciesId':p['ID especie'],'sourceScientific':n,'scientific':canonical(n),'regionId':rids[p['Región']],'id':ids[canonical(n)],'sourceBiome':p['Bioma'],'sourceRarity':p['Rareza (juego)'],'subareaNote':byrow.get(row,{}).get('decision','Presencia ilustrativa en los hábitats compatibles de esta región amplia; no implica ocupar todo el hexágono.'),'geographicStatus':byrow.get(row,{}).get('status','source-retained'),'status':'source-concept-unresolved'if decisions.get(n,{}).get('status')=='source-concept-unresolved'else'kept-with-subarea'if row in byrow else'source-retained'})
