data={'taxa':taxa,'version':'3.23.0','sourceSha256':'5cd22412e6b251d8f02a90e4c8303e02946d5e5d26855589d2c6750649fe4350','sourceNames':131,'canonicalSpecies':131,'aliases':aliases,'ids':ids,'species':new,'regions':regions,'dimorphism':dim,'categories':categories,'presences':source,'access':{'researchId':'sudamerica_1','requires':'norteamerica_1','money':3400,'knowledge':3000,'regionPrestige':{'min':167,'max':194},'newItems':[]}}
js='/* AM-04: verified source presences; ecology, variants and art are explicit game design. */\n(function(root){\n\'use strict\';\nconst data='+json.dumps(data,ensure_ascii=False,separators=(',',':'))+';\nroot.AtlasSouthAmerica3230=data;if(typeof module===\'object\'&&module.exports)module.exports=data;\n})(typeof globalThis!==\'undefined\'?globalThis:this);\n'
(root/'www/js/southamerica-data-v3230.js').write_text(js);(root/'docs/sudamerica-v3230/source-presences.json').write_text(json.dumps(source,ensure_ascii=False,indent=2)+'\n')
